import random
Is=[I3,I4]
Os=[O3full,O4full]
Qs=[(0,5),(5,0),(5,5)]
def compatible(p,q):
 r,c=Qs[q]
 for I,O in zip(Is,Os):
  for d,src in enumerate(p):
   if O[r+d//5,c+d%5] != I.flat[src]: return False
 return True

